import RNA
import random
import sys, time
from multiprocessing import Pool

target = "(((((((((((((((((...(.(..((.(((.(((.((....).))).)))).).)..))..))))))).(((((..(.(..((.(((.(((((.(((.((((.((....).)))).))))).))).)))).).)..))..)((....))..))))(((((((((...))))).(((((...)))))(.(....).).)))).)))).((((.((((...(((((((...))))))).(((((...)))))))))(((((((...))))))).(((((...)))))))))((((..((....))(..((..(..(.(.(((.((((.((....).)))).)))).)..)..).))..))))).))))))."
N = len(target)
assert N == 370

pair=[-1]*N; stack=[]
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop(); pair[i]=j; pair[j]=i
paired=[pair[i]!=-1 for i in range(N)]

COMP={'A':'U','U':'A','G':'C','C':'G'}

md = RNA.md()
md.dangles=2
md.temperature=310.15

def fold_seq(seq):
    fc = RNA.fold_compound(seq, md)
    return fc.mfe()

def parse_pairs(struct):
    sp=[-1]*N; st=[]
    for i,c in enumerate(struct):
        if c=='(': st.append(i)
        elif c==')':
            j=st.pop(); sp[i]=j; sp[j]=i
    return sp

def diagnose(seq):
    struct,e = fold_seq(seq)
    sp=parse_pairs(struct)
    missing=[]; spurious=[]
    for i in range(N):
        if pair[i]!=-1 and i<pair[i]:
            if sp[i]!=pair[i]:
                missing.append((i,pair[i]))
        if sp[i]!=-1 and i<sp[i]:
            if sp[i]!=pair[i]:
                spurious.append((i,sp[i]))
    return struct, missing, spurious

def cost(struct):
    sp=parse_pairs(struct)
    d=0
    for i in range(N):
        if (sp[i]!=-1) != (pair[i]!=-1):
            d+=1
        elif sp[i]!=-1 and pair[i]!=-1 and sp[i]!=pair[i]:
            d+=2
    return d

def build_init(rng):
    seq=['A']*N
    i=0; stems=[]
    while i<N:
        if paired[i]:
            j=pair[i]; L=0
            while i+L<N and pair[i+L]==j-L and pair[i+L]!=-1: L+=1
            stems.append((i,j,L)); i+=L
        else: i+=1
    # Stems: mix GC and AU; use GC for short stems (length 1-2), GC for longer
    for (si,sj,L) in stems:
        for k in range(L):
            left=si+k; right=sj-k
            # Use GC predominantly
            if k%2==0: seq[left]='G'; seq[right]='C'
            else: seq[left]='C'; seq[right]='G'
    # hairpin loops
    for (si,sj,L) in stems:
        ci=si+L-1; cj=sj-L+1
        inner=list(range(ci+1,cj))
        if all(not paired[k] for k in inner):
            ll=len(inner)
            if ll==4: seq[inner[0]]='U';seq[inner[1]]='U';seq[inner[2]]='C';seq[inner[3]]='G'
            elif ll==3: seq[inner[0]]='G';seq[inner[1]]='A';seq[inner[2]]='A'
    # BREAK long-range complementarity: in multiloop/junction unpaired regions,
    # mutate to A (non-pairing) with some U
    return ''.join(seq)

def directed_mutate(seq, rng):
    """Pick a spurious pair and break it; or pick a missing pair and fix it."""
    struct, missing, spurious = diagnose(seq)
    cand=list(seq)
    if spurious and (not missing or rng.random()<0.6):
        # break a spurious pair: change one partner to non-complement
        i,j = rng.choice(spurious)
        # choose to mutate the one that's NOT in a target pair, or either
        # mutate to break complementarity
        target_partner_i = pair[i]
        for pos in (i,j):
            if pair[pos]==-1:
                # unpaired in target: set to A or U (non-pairing with the other)
                other = j if pos==i else i
                other_base = seq[other]
                noncomp = [b for b in 'ACGU' if COMP[b]!=other_base]
                cand[pos]=rng.choice(noncomp)
                break
        else:
            # both are paired in target; mutate the one whose target partner won't be affected
            # just set i to a base that doesn't pair with j but try to keep target pair valid
            # Actually if i is paired in target with pair[i], keep seq[i]=comp of pair[i]'s base
            # This is complex; just random mutate j
            cand[j]=rng.choice('ACGU')
    elif missing:
        i,j = rng.choice(missing)
        # fix: make seq[i] and seq[j] complementary
        b = rng.choice('GCA')  # prefer G/C
        cand[i]=b; cand[j]=COMP[b]
    return ''.join(cand)

def run_anneal(seed, tlimit):
    rng = random.Random(seed)
    cur = build_init(rng)
    cur_struct, _ = fold_seq(cur)
    cur_d = cost(cur_struct)
    best=cur; best_d=cur_d; best_struct=cur_struct
    T=2.0
    t0=time.time()
    while time.time()-t0 < tlimit:
        # directed mutation sometimes, random sometimes
        if rng.random()<0.7:
            cand = directed_mutate(cur, rng)
        else:
            cand=list(cur)
            for _ in range(rng.choice([1,1,2])):
                p=rng.randrange(N)
                cand[p]=rng.choice('ACGU')
            cand=''.join(cand)
        cs,_=fold_seq(cand)
        cd=cost(cs)
        if cd<=cur_d or rng.random()<pow(2.718,-(cd-cur_d)/max(T,0.3)):
            cur=cand; cur_d=cd; cur_struct=cs
            if cd<best_d:
                best=cand; best_d=cd; best_struct=cs
                if cd==0 and cs==target:
                    return best,0,best_struct
        T=max(0.1, T*0.9999)
    return best,best_d,best_struct

if __name__=='__main__':
    nproc=int(sys.argv[1]) if len(sys.argv)>1 else 64
    tlimit=int(sys.argv[2]) if len(sys.argv)>2 else 170
    args=[(s,tlimit) for s in range(nproc)]
    with Pool(nproc) as p:
        results=p.starmap(run_anneal, args)
    results.sort(key=lambda x:x[1])
    best,bd,bs=results[0]
    print("best_d",bd)
    print("BEST",best)
    print("STRUCT",bs)
    print("MATCH", bs==target)
    for i,(b,d,s) in enumerate(results[:10]):
        print(f"r{i} d={d}")
